#pragma once
#include <cstdint>
namespace ks{
class GlobalTableTask final{public:enum class Stage{ReadSelector,CompareSelector,AdmitSelector,ClampSelector,SetStride,LocateRow,ClearUpper,BindSource,BindDestination,SetRemaining,ReadWord,WriteWord,TickDestination,TickRemaining,AdmitRemaining,Complete};Stage stage()const{return stage_;}uint8_t selector()const{return selector_;}uint16_t rowOffset()const{return rowOffset_;}uint8_t index()const{return index_;}uint16_t word()const{return word_;}uint16_t remaining()const{return remaining_;}unsigned nextClocks()const{switch(stage_){case Stage::ReadSelector:return 15;case Stage::LocateRow:return 15;case Stage::BindSource:case Stage::BindDestination:return 9;case Stage::SetRemaining:return 6;case Stage::ReadWord:return 8;case Stage::WriteWord:return 6;case Stage::Complete:return 0;default:return 3;}}
 template<class Reader,class Writer>unsigned advanceBefore(unsigned available,Reader&&read,Writer&&write){unsigned used=0;while(auto cost=nextClocks()){if(cost>available-used)break;switch(stage_){case Stage::ReadSelector:selector_=uint8_t(read(true));stage_=Stage::CompareSelector;break;case Stage::CompareSelector:stage_=Stage::AdmitSelector;break;case Stage::AdmitSelector:stage_=selector_<=5?Stage::SetStride:Stage::ClampSelector;break;case Stage::ClampSelector:selector_=5;stage_=Stage::SetStride;break;case Stage::SetStride:stage_=Stage::LocateRow;break;case Stage::LocateRow:rowOffset_=unsigned(selector_)*20;stage_=Stage::ClearUpper;break;case Stage::ClearUpper:stage_=Stage::BindSource;break;case Stage::BindSource:stage_=Stage::BindDestination;break;case Stage::BindDestination:stage_=Stage::SetRemaining;break;case Stage::SetRemaining:remaining_=10;stage_=Stage::ReadWord;break;case Stage::ReadWord:word_=uint16_t(read(false));stage_=Stage::WriteWord;break;case Stage::WriteWord:write(word_);stage_=Stage::TickDestination;break;case Stage::TickDestination:++index_;stage_=Stage::TickRemaining;break;case Stage::TickRemaining:--remaining_;stage_=Stage::AdmitRemaining;break;case Stage::AdmitRemaining:stage_=remaining_?Stage::ReadWord:Stage::Complete;break;default:break;}used+=cost;}return used;}
private:Stage stage_=Stage::ReadSelector;uint8_t selector_=0,index_=0;uint16_t rowOffset_=0,word_=0,remaining_=0;
};}
